(E'Anacostia River', E'anacostia-river-137', E'The nation''s capital offers surprisingly excellent urban fishing along the revitalized Anacostia River. Northern snakehead, an invasive but exciting gamefish, has made this a unique fishing destination.', E'Virginia', E'Washington', NULL, E'USA', E'Anacostia River, Washington, DC 20003', E'38.880000', E'-76.970000', E'river', NULL, E'f', E't', E't', E'Free (DC License Required)', E'Spring & Summer', E'Target snakehead in shallow weedy areas with topwater frogs\nFish Kenilworth Aquatic Gardens for bass and snakehead\nBlue catfish are abundant - use cut shad on the bottom\nThe Anacostia Riverwalk Trail provides great bank access', NULL, NULL, E'active', E'2026-09-23 06:24:32.378233+00', E'2026-09-23 06:24:32.378233+00', E'137'),
(E'Prospect Park Lake', E'prospect-park-lake-127', E'Brooklyn''s beloved urban fishing destination in Frederick Law Olmsted''s masterpiece park. The 60-acre lake offers surprisingly good fishing just minutes from downtown Brooklyn.', E'New York', E'Brooklyn', NULL, E'USA', E'Prospect Park, Brooklyn, NY 11215', E'40.660200', E'-73.969000', E'lake', NULL, E't', E'f', E't', E'Free (Catch & Release Only)', E'Spring & Summer', E'Fish the Lullwater area for the best bass habitat\nUse bread balls for carp along the shoreline\nEarly morning weekdays offer the most peaceful fishing\nBring your own gear - no loaner programs available', NULL, NULL, E'active', E'2026-09-23 06:24:23.949556+00', E'2026-09-23 06:24:23.949556+00', E'127'),
(E'Chatfield State Park Kids'' Pond', E'chatfield-state-park-kids-pond-142', E'Colorado''s best kids'' fishing destination with a dedicated children''s pond stocked weekly during summer. The shallow, accessible pond has paved paths, benches, and guaranteed catches for young anglers.', E'Colorado', E'Littleton', NULL, E'USA', E'Chatfield State Park, Littleton, CO 80125', E'39.530000', E'-105.070000', E'lake', NULL, E'f', E't', E't', E'State Park Fee ($10/vehicle)', E'Summer', E'The kids'' pond is stocked every Thursday - fish Friday morning for best results\nUse worms under a bobber for bluegill - perfect for beginners\nPowerBait in bright colors works great for stocked trout\nBring a picnic - there are tables and shade right by the pond', NULL, NULL, E'active', E'2026-09-23 06:24:36.080037+00', E'2026-09-23 06:24:36.080037+00', E'142'),
(E'Lake Merritt', E'lake-merritt-135', E'America''s oldest wildlife refuge is also a unique urban fishing spot in downtown Oakland. This tidal lagoon connected to San Francisco Bay offers surprising saltwater species in a city setting.', E'California', E'Oakland', NULL, E'USA', E'Lake Merritt, Oakland, CA 94612', E'37.800000', E'-122.250000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Fall', E'Fish incoming tides for striped bass near the channel\nTarget bat rays with squid on the bottom at night\nUse pile worms for perch along the shoreline\nThe 12th Street bridge area is the most productive spot', NULL, NULL, E'active', E'2026-09-23 06:24:30.437074+00', E'2026-09-23 06:24:30.437074+00', E'135'),
(E'Henry''s Lake', E'henry-s-lake-153', E'One of the premier trophy trout lakes in the West, producing cutthroat trout averaging 3-5 lbs. Located near Yellowstone, it''s a must-visit for serious trout anglers.', E'Idaho', E'Island Park', NULL, E'USA', E'Henry''s Lake, Island Park, ID 83429', E'44.610000', E'-111.380000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Fall', E'Fish leeches and damselfly nymphs for trophy cutthroat\nFloat tube fishing is the most effective method\nTarget the inlet streams in early summer for cruising fish\nUse woolly buggers stripped slowly along weed edges', NULL, NULL, E'active', E'2026-09-23 06:24:45.335628+00', E'2026-09-23 06:24:45.335628+00', E'153'),
(E'Westmoreland Park Casting Pond', E'westmoreland-park-casting-pond-140', E'Portland''s beloved urban fishing pond in the heart of SE Portland. Stocked with rainbow trout by ODFW, it''s a perfect spot for teaching kids to fish with easy bank access and a playground nearby.', E'Oregon', E'Portland', NULL, E'USA', E'Westmoreland Park, Portland, OR 97202', E'45.470000', E'-122.650000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring', E'Fish right after ODFW stocking for best trout action\nUse PowerBait or worms under a bobber for kids\nThe east bank has the deepest water and best trout holding areas\nCombine fishing with a visit to the adjacent playground', NULL, NULL, E'active', E'2026-09-23 06:24:34.713867+00', E'2026-09-23 06:24:34.713867+00', E'140'),
(E'Lady Bird Lake', E'lady-bird-lake-131', E'Austin''s iconic downtown reservoir on the Colorado River, home to the state fish - the Guadalupe Bass. Kayak and paddleboard fishing are popular with stunning skyline views.', E'Texas', E'Austin', NULL, E'USA', E'Lady Bird Lake, Austin, TX 78701', E'30.250000', E'-97.750000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Kayak fish the coves near Red Bud Isle for bass\nTarget Guadalupe bass near rocky structure with small crankbaits\nFish under the Congress Avenue Bridge at dawn for best action\nMotorized boats are prohibited - paddle craft only', NULL, NULL, E'active', E'2026-09-23 06:24:26.876195+00', E'2026-09-23 06:24:26.876195+00', E'131'),
(E'Burke Lake', E'burke-lake-143', E'Northern Virginia''s premier family fishing lake with a fishing pier, boat rentals, playground, carousel, and mini-train. The 218-acre lake is stocked regularly and offers excellent shoreline access.', E'Virginia', E'Fairfax Station', NULL, E'USA', E'Burke Lake Park, Fairfax Station, VA 22039', E'38.760000', E'-77.290000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Fish from the pier for easy access with kids\nUse nightcrawlers under a bobber for bluegill and crappie\nRent a rowboat to access deeper bass and catfish areas\nThe marina cove is the best spot for young anglers', NULL, NULL, E'active', E'2026-09-23 06:24:36.755834+00', E'2026-09-23 06:24:36.755834+00', E'143'),
(E'Lake Ella', E'lake-ella-144', E'Tallahassee''s charming urban lake surrounded by shops and restaurants. The small, accessible lake is perfect for introducing kids to fishing with easy shoreline access and shallow water.', E'Florida', E'Tallahassee', NULL, E'USA', E'Lake Ella, Tallahassee, FL 32303', E'30.460000', E'-84.280000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Year-round', E'Use bread balls for tilapia and carp - kids love the instant action\nFish worms under a bobber for bluegill along the shore\nTarget bass near the fountain with small plastic worms\nCombine fishing with a treat from the surrounding shops', NULL, NULL, E'active', E'2026-09-23 06:24:37.400751+00', E'2026-09-23 06:24:37.400751+00', E'144'),
(E'Greenfield Lake', E'greenfield-lake-145', E'A beautiful cypress-lined lake in Wilmington with a 5-mile trail, playground, and amphitheater. The shallow, warm lake is perfect for kids with easy bank access and abundant panfish.', E'North Carolina', E'Wilmington', NULL, E'USA', E'Greenfield Lake Park, Wilmington, NC 28401', E'34.210000', E'-77.940000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Fish near the cypress trees for bass with plastic worms\nUse crickets for bluegill along the walking trail\nThe fishing pier near the amphitheater is great for kids\nWatch for alligators - they''re part of the experience!', NULL, NULL, E'active', E'2026-09-23 06:24:38.079186+00', E'2026-09-23 06:24:38.079186+00', E'145'),
(E'Killens Pond', E'killens-pond-151', E'Delaware''s most popular family fishing destination with a water park, nature center, and campground. The 66-acre pond is stocked regularly and has excellent shoreline access.', E'Delaware', E'Felton', NULL, E'USA', E'Killens Pond State Park, Felton, DE 19943', E'39.020000', E'-75.540000', E'lake', NULL, E't', E'f', E't', E'State Park Fee + License', E'Spring & Summer', E'Fish from the pier near the nature center for easy panfish\nUse worms and bobbers for bluegill - perfect for kids\nTarget bass in the lily pads with topwater frogs\nCombine fishing with the water park for a full family day', NULL, NULL, E'active', E'2026-09-23 06:24:43.042332+00', E'2026-09-23 06:24:43.042332+00', E'151'),
(E'Mirror Lake State Park', E'mirror-lake-state-park-147', E'A stunning sandstone-cliff lake near Wisconsin Dells, perfect for combining family vacation with fishing. The calm, clear water and sandy beaches make it ideal for kids.', E'Wisconsin', E'Baraboo', NULL, E'USA', E'Mirror Lake State Park, Baraboo, WI 53913', E'43.560000', E'-89.800000', E'lake', NULL, E'f', E't', E't', E'State Park Fee ($8/vehicle)', E'Summer', E'Fish from the canoe/kayak for best access to bass habitat\nUse worms near the sandy beach for bluegill with kids\nTarget pike in the lily pads at the north end\nCombine with a visit to nearby Wisconsin Dells attractions', NULL, NULL, E'active', E'2026-09-23 06:24:40.261391+00', E'2026-09-23 06:24:40.261391+00', E'147'),
(E'Ala Wai Canal', E'ala-wai-canal-152', E'Waikiki''s urban fishing canal where locals and tourists fish for papio and tilapia. An accessible spot just steps from the famous beach, offering a unique tropical urban fishing experience.', E'Hawaii', E'Honolulu', NULL, E'USA', E'Ala Wai Canal, Honolulu, HI 96815', E'21.280000', E'-157.830000', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Year-round', E'Fish the mouth near the harbor for papio on incoming tides\nUse bread balls or shrimp for tilapia along the canal walls\nEarly morning and evening are best to avoid the heat\nBring a net - the canal walls make landing fish tricky', NULL, NULL, E'active', E'2026-09-23 06:24:43.711355+00', E'2026-09-23 06:24:43.711355+00', E'152'),
(E'Wabash River', E'wabash-river-32', E'Indiana''s official state river with excellent smallmouth and catfish.', E'Indiana', E'Lafayette', NULL, E'USA', E'Wabash River, Lafayette, IN 47901', E'40.416700', E'-86.875300', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer', E'Wade fish riffles for smallmouth with tube jigs\nFish deep holes for flathead catfish at night\nTarget dam tailwaters for sauger in fall', NULL, NULL, E'active', E'2026-09-23 06:23:12.701814+00', E'2026-09-23 06:23:12.701814+00', E'32'),
(E'Clear Lake', E'clear-lake-154', E'Iowa''s third-largest natural lake and a popular family vacation destination. Known for excellent yellow bass fishing and a charming lakeside town with resorts and restaurants.', E'Iowa', E'Clear Lake', NULL, E'USA', E'Clear Lake, Clear Lake, IA 50428', E'43.140000', E'-93.380000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Winter', E'Target yellow bass schools with small jigs and minnows\nFish the rock reefs for walleye at dawn and dusk\nIce fishing for walleye and perch is outstanding\nThe south shore has the best family-friendly access points', NULL, NULL, E'active', E'2026-09-23 06:24:46.395551+00', E'2026-09-23 06:24:46.395551+00', E'154'),
(E'El Dorado Reservoir', E'el-dorado-reservoir-155', E'Kansas'' most popular state park lake with 8,000 acres of excellent multi-species fishing. The park offers camping, swimming beaches, and extensive shoreline access for families.', E'Kansas', E'El Dorado', NULL, E'USA', E'El Dorado State Park, El Dorado, KS 67042', E'37.820000', E'-96.860000', E'lake', NULL, E'f', E't', E't', E'State Park Fee + License', E'Spring & Fall', E'Fish the white bass run at the Walnut River inlet in spring\nTroll for walleye with bottom bouncers along the dam\nTarget crappie in brush piles near the marina\nNight fishing for catfish at the spillway is excellent', NULL, NULL, E'active', E'2026-09-23 06:24:47.362949+00', E'2026-09-23 06:24:47.362949+00', E'155'),
(E'Wachusett Reservoir', E'wachusett-reservoir-158', E'Central Massachusetts'' premier cold-water fishery and Boston''s drinking water supply. Shore fishing only with strict regulations, but produces trophy lake trout and salmon.', E'Massachusetts', E'West Boylston', NULL, E'USA', E'Wachusett Reservoir, West Boylston, MA 01583', E'42.380000', E'-71.720000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Shore fish only - no boats allowed on this reservoir\nCast large spoons for lake trout from accessible points\nFish the spring stocking for rainbow and brown trout\nThe south shore access points offer the best casting', NULL, NULL, E'active', E'2026-09-23 06:24:49.931209+00', E'2026-09-23 06:24:49.931209+00', E'158'),
(E'Worden Pond', E'worden-pond-165', E'Rhode Island''s largest freshwater body at 1,043 acres. A shallow, weedy lake that produces trophy largemouth bass and pickerel in a peaceful, undeveloped setting.', E'Rhode Island', E'Wakefield', NULL, E'USA', E'Worden Pond, Wakefield, RI 02879', E'41.420000', E'-71.680000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Fish the weed edges for trophy largemouth with frogs and buzzbaits\nTarget pickerel in the lily pads with spinnerbaits\nUse worms under a bobber for perch and bluegill\nCanoe or kayak access opens up the best fishing areas', NULL, NULL, E'active', E'2026-09-23 06:24:55.440791+00', E'2026-09-23 06:24:55.440791+00', E'165'),
(E'Blue Mesa Reservoir', E'blue-mesa-reservoir-15', E'Colorado''s largest body of water with excellent kokanee and lake trout fishing.', E'Colorado', E'Gunnison', NULL, E'USA', E'Blue Mesa Reservoir, Gunnison, CO 81230', E'38.450000', E'-107.330000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer', E'Troll for kokanee with wedding ring spinners\nJig for lake trout near the dam in winter\nFish tributary inlets in spring for rainbows', NULL, NULL, E'active', E'2026-09-23 06:22:56.424758+00', E'2026-09-23 06:22:56.424758+00', E'15'),
(E'Liberty Reservoir', E'liberty-reservoir-157', E'Baltimore''s drinking water reservoir offering trophy brown trout and tiger muskie fishing. Electric motors only create a peaceful, uncrowded fishing experience.', E'Maryland', E'Eldersburg', NULL, E'USA', E'Liberty Reservoir, Eldersburg, MD 21784', E'39.420000', E'-76.920000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Troll for brown trout with Rapala minnows in spring\nTarget tiger muskie with large jerkbaits near rocky points\nFish the upper arms for bass in the warmer months\nElectric motors only - plan for a quiet, peaceful trip', NULL, NULL, E'active', E'2026-09-23 06:24:48.958406+00', E'2026-09-23 06:24:48.958406+00', E'157'),
(E'Squam Lake', E'squam-lake-161', E'The filming location of ''On Golden Pond'' and one of New Hampshire''s most pristine lakes. Excellent cold-water fishing in a stunning natural setting with loon calls echoing across the water.', E'New Hampshire', E'Holderness', NULL, E'USA', E'Squam Lake, Holderness, NH 03245', E'43.760000', E'-71.610000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Troll for salmon with lead core line in spring after ice-out\nFish the islands for smallmouth bass with crawfish patterns\nTarget lake trout deep near Rattlesnake Island\nRespect the peaceful atmosphere - this is a quiet lake', NULL, NULL, E'active', E'2026-09-23 06:24:52.766869+00', E'2026-09-23 06:24:52.766869+00', E'161'),
(E'Merritt Reservoir', E'merritt-reservoir-160', E'A Sandhills gem known for trophy muskie and walleye in a remote, scenic setting. The clear water and abundant forage produce exceptional fish growth rates.', E'Nebraska', E'Valentine', NULL, E'USA', E'Merritt Reservoir, Valentine, NE 69201', E'42.050000', E'-100.160000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Fall', E'Target muskie with large bucktails and jerkbaits in fall\nFish rocky points for walleye at dawn with jigs and minnows\nThe Snake River arm has the best bass fishing\nNight fishing for walleye near the dam is very productive', NULL, NULL, E'active', E'2026-09-23 06:24:52.116535+00', E'2026-09-23 06:24:52.116535+00', E'160'),
(E'Spruce Run Reservoir', E'spruce-run-reservoir-162', E'Central New Jersey''s top multi-species fishery with 1,290 acres of excellent fishing. The reservoir is stocked with trout and hybrid stripers, and has a swimming beach and campground.', E'New Jersey', E'Clinton', NULL, E'USA', E'Spruce Run Recreation Area, Clinton, NJ 08809', E'40.660000', E'-74.860000', E'lake', NULL, E'f', E't', E't', E'State Park Fee + License', E'Spring & Summer', E'Troll for hybrid stripers with crankbaits near the dam\nFish the inlet area for trout after spring stocking\nTarget pike in the weed beds with large spinnerbaits\nThe south shore has the best family-friendly access', NULL, NULL, E'active', E'2026-09-23 06:24:53.416719+00', E'2026-09-23 06:24:53.416719+00', E'162'),
(E'Flathead Lake', E'flathead-lake-159', E'The largest natural freshwater lake west of the Mississippi, with crystal-clear water and stunning Mission Mountain views. Trophy lake trout over 30 lbs are caught annually.', E'Montana', E'Polson', NULL, E'USA', E'Flathead Lake, Polson, MT 59860', E'47.880000', E'-114.150000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Fall', E'Troll deep for lake trout with large spoons and downriggers\nFish the east shore for yellow perch with small jigs\nTarget bull trout near river mouths in fall - catch and release only\nThe Narrows area between Big and Little Flathead is prime', NULL, NULL, E'active', E'2026-09-23 06:24:50.547055+00', E'2026-09-23 06:24:50.547055+00', E'159'),
(E'Heron Lake', E'heron-lake-163', E'New Mexico''s premier cold-water fishery at 7,186 feet elevation. A no-wake lake offering peaceful fishing for kokanee salmon and trophy trout in a stunning mountain setting.', E'New Mexico', E'Los Ojos', NULL, E'USA', E'Heron Lake State Park, Los Ojos, NM 87551', E'36.670000', E'-106.730000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer & Fall', E'Troll for kokanee with dodger and fly combos in summer\nFish deep for lake trout with large spoons near the dam\nShore fish for stocked rainbow trout with PowerBait\nThe no-wake rule makes this perfect for kayak fishing', NULL, NULL, E'active', E'2026-09-23 06:24:54.077253+00', E'2026-09-23 06:24:54.077253+00', E'163'),
(E'Lake Memphremagog', E'lake-memphremagog-167', E'A stunning international lake straddling the US-Canada border with excellent cold-water fishing. The deep, clear water produces trophy salmon and lake trout in a beautiful mountain setting.', E'Vermont', E'Newport', NULL, E'USA', E'Lake Memphremagog, Newport, VT 05855', E'44.940000', E'-72.200000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Troll for salmon with streamer flies in spring\nFish the South Bay for walleye and pike\nTarget smallmouth on rocky shoals with tube jigs\nThe deep basin near the border produces trophy lakers', NULL, NULL, E'active', E'2026-09-23 06:24:57.134322+00', E'2026-09-23 06:24:57.134322+00', E'167'),
(E'Big Sioux River', E'big-sioux-river-166', E'An underrated urban fishery flowing through Sioux Falls with excellent walleye and catfish. Falls Park provides a scenic backdrop for fishing in the heart of the city.', E'South Dakota', E'Sioux Falls', NULL, E'USA', E'Big Sioux River, Sioux Falls, SD 57104', E'43.550000', E'-96.730000', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Fish below the falls for walleye with jigs and minnows\nTarget catfish in deep pools with cut bait\nWade fish the riffles for smallmouth in summer\nThe stretch through town has multiple public access points', NULL, NULL, E'active', E'2026-09-23 06:24:56.433486+00', E'2026-09-23 06:24:56.433486+00', E'166'),
(E'Bighorn River', E'bighorn-river-169', E'One of the finest tailwater trout fisheries in the world below Boysen Reservoir. The nutrient-rich water produces trout averaging 16-18 inches with fish over 20 inches common.', E'Wyoming', E'Thermopolis', NULL, E'USA', E'Bighorn River, Thermopolis, WY 82443', E'43.650000', E'-108.210000', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Year-round', E'Fish scuds and sowbugs below the dam for trophy trout\nUse San Juan worms during high water for consistent action\nFloat the Wedding of the Waters section for best access\nDry fly fishing is excellent during summer caddis hatches', NULL, NULL, E'active', E'2026-09-23 06:24:58.464366+00', E'2026-09-23 06:24:58.464366+00', E'169'),
(E'Stonewall Jackson Lake', E'stonewall-jackson-lake-168', E'A scenic 2,650-acre lake with a resort lodge, golf course, and excellent family fishing. The lake is managed for trophy bass and muskie with strict slot limits.', E'West Virginia', E'Roanoke', NULL, E'USA', E'Stonewall Jackson Lake State Park, Roanoke, WV 26423', E'38.880000', E'-80.460000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Summer', E'Fish the standing timber for crappie with jigs and minnows\nTarget bass along the shoreline with spinnerbaits in spring\nThe upper arms have the best muskie habitat\nRent a boat from the marina for best access to fishing spots', NULL, NULL, E'active', E'2026-09-23 06:24:57.794458+00', E'2026-09-23 06:24:57.794458+00', E'168'),
(E'Garrison Dam Tailrace', E'garrison-dam-tailrace-164', E'One of the most productive tailwater fisheries in the northern plains. The cold, oxygen-rich water below Garrison Dam supports incredible walleye and salmon fishing year-round.', E'North Dakota', E'Riverdale', NULL, E'USA', E'Garrison Dam, Riverdale, ND 58565', E'47.510000', E'-101.420000', E'dam', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Fish jigs tipped with minnows for walleye near the discharge\nTarget chinook salmon with spoons in the fast water\nThe bank fishing access is excellent on both sides\nWinter fishing for walleye below the dam is outstanding', NULL, NULL, E'active', E'2026-09-23 06:24:54.785698+00', E'2026-09-23 06:24:54.785698+00', E'164'),
(E'Beaver Lake', E'beaver-lake-170', E'Northwest Arkansas'' premier lake in the heart of the Ozarks. Crystal-clear water, stunning bluffs, and excellent multi-species fishing make it a top family destination.', E'Arkansas', E'Rogers', NULL, E'USA', E'Beaver Lake, Rogers, AR 72756', E'36.350000', E'-93.850000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Fish the bluffs for spotted bass with jerkbaits and drop shots\nTarget stripers near the dam with live shad in summer\nThe War Eagle Creek arm has the best crappie fishing\nWalleye fishing is excellent near the dam in winter', NULL, NULL, E'active', E'2026-09-23 06:24:59.122932+00', E'2026-09-23 06:24:59.122932+00', E'170'),
(E'Lake Guntersville', E'lake-guntersville-1', E'Consistently ranked as one of the best bass lakes in America with massive grass beds.', E'Alabama', E'Guntersville', NULL, E'USA', E'Lake Guntersville, Guntersville, AL 35976', E'34.350100', E'-86.293900', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Fish the grass edges with swimbaits in spring\nTarget bridge pilings for crappie in winter\nUse topwater frogs over matted vegetation in summer', NULL, NULL, E'active', E'2026-09-23 06:22:43.241443+00', E'2026-09-23 06:22:43.241443+00', E'1'),
(E'Norris Lake', E'norris-lake-89', E'Crystal-clear TVA lake with outstanding striped bass and walleye.', E'Tennessee', E'Rocky Top', NULL, E'USA', E'Norris Lake, Rocky Top, TN 37769', E'36.220000', E'-84.080000', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Fish the thermocline for stripers in summer\nTarget walleye near the dam with jigs\nFish rocky banks for smallmouth with crawfish', NULL, NULL, E'active', E'2026-09-23 06:23:57.057699+00', E'2026-09-23 06:23:57.057699+00', E'89'),
(E'Lincoln Park Lagoon', E'lincoln-park-lagoon-128', E'A hidden urban fishing gem in Chicago''s most popular park. The South Lagoon offers peaceful fishing with stunning skyline views, and the Chicago Park District hosts free family fishing events.', E'Illinois', E'Chicago', NULL, E'USA', E'Lincoln Park, Chicago, IL 60614', E'41.921400', E'-87.635200', E'lake', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer', E'Fish the South Lagoon near Café Brauer for best access\nUse worms and bobbers for guaranteed bluegill action with kids\nTarget catfish at dusk with chicken liver or stink bait\nJoin the free Chicago Park District fishing programs in summer', NULL, NULL, E'active', E'2026-09-23 06:24:24.932447+00', E'2026-09-23 06:24:24.932447+00', E'128'),
(E'Mississippi River - Pool 9', E'mississippi-river-pool-9-34', E'Incredible backwater fishing on the Upper Mississippi with diverse species.', E'Iowa', E'Lansing', NULL, E'USA', E'Mississippi River, Lansing, IA 52151', E'43.360000', E'-91.220000', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Spring & Fall', E'Fish wing dams for walleye with jigs\nTarget backwater sloughs for bass and bluegill\nUse cut shad for catfish in the main channel', NULL, NULL, E'active', E'2026-09-23 06:23:14.70386+00', E'2026-09-23 06:23:14.70386+00', E'34'),
(E'New River', E'new-river-102', E'Ancient river with spectacular gorge scenery and excellent smallmouth fishing.', E'West Virginia', E'Fayetteville', NULL, E'USA', E'New River Gorge, Fayetteville, WV 25840', E'38.060000', E'-81.080000', E'river', NULL, E't', E'f', E't', E'Free (License Required)', E'Summer', E'Float the gorge section for smallmouth with tubes\nFish deep pools for flathead catfish at night\nTarget muskie in the lower river with large lures', NULL, NULL, E'active', E'2026-09-23 06:24:06.688328+00', E'2026-09-23 06:24:06.688328+00', E'102');
