CREATE TABLE public.fishing_spots (
    name text NOT NULL,
    slug text NOT NULL,
    description text,
    state text NOT NULL,
    city text,
    county text,
    country text DEFAULT 'USA'::text NOT NULL,
    address text,
    latitude numeric(9,6),
    longitude numeric(9,6),
    water_type text DEFAULT 'lake'::text NOT NULL,
    access_type text,
    public_access boolean DEFAULT false NOT NULL,
    private_access boolean DEFAULT false NOT NULL,
    permit_required boolean DEFAULT false NOT NULL,
    permit_information text,
    best_seasons text,
    fishing_notes text,
    image_url text,
    website_url text,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    id integer NOT NULL,
    CONSTRAINT fishing_spots_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'draft'::text])))
);

ALTER TABLE public.fishing_spots ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.fishing_spots_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


ALTER TABLE ONLY public.fishing_spots ADD CONSTRAINT fishing_spots_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.fishing_spots ADD CONSTRAINT fishing_spots_slug_key UNIQUE (slug);

ALTER TABLE ONLY public.fishing_spot_species ADD CONSTRAINT fishing_spot_species_spot_fk FOREIGN KEY (fishing_spot_id) REFERENCES public.fishing_spots(id) ON DELETE CASCADE;

CREATE INDEX fishing_spots_city_idx ON public.fishing_spots USING btree (city);

CREATE INDEX fishing_spots_coordinates_idx ON public.fishing_spots USING btree (latitude, longitude);

CREATE INDEX fishing_spots_name_search_idx ON public.fishing_spots USING gin (to_tsvector('simple'::regconfig, ((((name || ' '::text) || COALESCE(city, ''::text)) || ' '::text) || state)));

CREATE INDEX fishing_spots_state_idx ON public.fishing_spots USING btree (state);

CREATE INDEX fishing_spots_status_idx ON public.fishing_spots USING btree (status);

CREATE INDEX fishing_spots_water_type_idx ON public.fishing_spots USING btree (water_type);

SELECT setval('public.fishing_spots_id_seq', COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.fishing_spots;